# Canvas notes for the Final page, written from the raw results and the single status record.
import json, pathlib, re
R = pathlib.Path('/tmp/claude-0/fx/run'); FX = pathlib.Path('/tmp/claude-0/fx'); W = pathlib.Path('/home/claude/work')
STATUS = json.loads((W / 'delivery-final' / 'status.json').read_text())
J = {w: json.loads((R / f'fxjourney-{w}.json').read_text()) for w in (1440, 1024, 768, 375)}
jr = ' · '.join(f"{sum(1 for r in J[w]['results'] if r['ok'])}/{len(J[w]['results'])}" for w in (1440, 1024, 768, 375))
axe = json.loads((R / 'axe.json').read_text()); focus = json.loads((R / 'focus.json').read_text()); trap = json.loads((R / 'trap.json').read_text())
fbad = [r for r in focus if r['problems']]
nren = sum(len(re.findall(r' @\d+ · ', (R / f).read_text())) for f in ('wA.log', 'wB.log', 'w320.log'))
ident = json.loads((FX / 'identity' / 'identity.json').read_text())
approved = STATUS['ownerApproval'] != 'PENDING'
title = 'Student · final complete-role design · all 19 screens · ' + (('approved by the owner, ' + STATUS.get('ownerApprovalDate', '')[8:10] + ' Oct 2026 · the one design to implement') if approved else 'waiting for the owner’s visual acceptance (not approved)')
st = [
 ('n-f-start', 'blue', 'Start here · Final preview (live)\nPress Play on “Final preview”. It is the whole Student role — all 19 screens with every scenario and state — as one design: one preview and one stylesheet. The dark strip on top is review-only; it switches scenario and screen.\nThe rows below show every screen and its states at 1440, 1024, 768, 375 and 320. Earlier generations are on the History page — superseded, not for integration.'),
 ('n-f-status', 'orange', 'Status · ' + STATUS['label'] + '\n' + ('Design complete (19 / 19) · connected preview complete · shared Account and Help borrowed (assembly pending XS) · ' + ('approved by the owner. The final source and screenshot ZIPs were generated from exactly this design; every earlier generation on the History page is superseded.' if approved else 'owner visual acceptance pending — not approved, not for implementation.\nAfter you accept it, the status is updated and the final source and screenshot ZIPs are generated from exactly this design.'))),
 ('n-f-merged', 'green', f'What was consolidated\nThe original design, checkpoint 1, checkpoint 2 and R2 are now one design. R2’s two layered role stylesheets became one, proven pixel-identical before any change ({sum(1 for r in ident if r["same"])} / {len(ident)} renders). Every earlier refinement is carried, superseded or reverted on record, and nothing is left pending (CONSOLIDATION-LEDGER.md).'),
 ('n-f-changed', 'green', 'What the final pass changed\nST-15 Progress: no box inside the card. Progress tables: one gutter, and two-column rows below 766 px (fixes a table wider than its card at 768–1024). ST-12: facts in two columns on phones, and the not-passed buttons reach the card edge. ST-05 Assessment tab: the button keeps its width on tablets. ST-11: tabs fit at 320. ST-17: answer words wrap at 320. Hover feedback on every control. Stage checks kept at 375.'),
 ('n-f-decide', 'pink', 'Decided, and still open\nDecided at approval: internal record identifiers (ACC-0107, SACC-0310, DTR-0018) are not labels on Student pages — presentation only, the records stay in the data, and every place is listed with how to restore it. Home keeps no shortcut links to the hub’s tabs. Still for the product owners: the sample activity’s three stages are illustrative — bind the real ones or remove the trackers before implementation; ended vs withdrawn, released results after access ends, course codes. HANDOFF.md.'),
 ('n-f-checked', 'purple', f'How it was checked\nChromium with the Design host’s runtime: {nren} renders (every case at 1440, 1024, 768 and 375, a subset at 320) — no overflow, spill, clipping, console error, duplicate ID or unnamed control (one borrowed XS link under 24 px). Journeys: {jr}. Keyboard: focus visible at every Tab stop on {len(focus) - len(fbad)} of {len(focus)} pages (the other {len(fbad)} are forced-open review presets), and kept inside the dialog, drawer and menu ({sum(1 for t in trap if t["ok"])} / {len(trap)}); hover on every control. axe: {sum(len(c["violations"]) for c in axe["cases"])} violations on {len(axe["cases"])} pages. Routing identical to the original in 690 cases. Not done: the Design editor itself, real screen readers, real devices.'),
]
json.dump({'title': title, 'stickies': [[k, {'fill': f, 'text': t}] for k, f, t in st]}, open(W / 'fx_notes.json', 'w'), ensure_ascii=False, indent=1)
print(title); [print('-', k, len(t)) for k, f, t in st]
